import {test} from 'node:test';import assert from 'node:assert/strict';
import {tileSelection,validateTileSource,validateTilePackage,tileRequest,openTilePackage} from './tiles-client.js';
const id='11111111-1111-4111-8111-111111111111',sha='a'.repeat(64);
const source=()=>({id,name:'Fixture only',url:'https://example.com/fixture.pmtiles',etag:'"fixture"',totalBytes:200,connectedAt:'2026-10-03T00:00:00Z',discoverySha256:sha,ranges:[{offset:0,bytes:127,sha256:sha},{offset:127,bytes:10,sha256:sha},{offset:137,bytes:10,sha256:sha}],header:{rootOffset:127,rootLength:10,metadataOffset:137,metadataLength:10,leafOffset:147,leafLength:0,tileOffset:147,tileLength:53,addressedTiles:1,tileEntries:1,tileContents:1,clustered:true,internalCompression:2,tileCompression:2,minZoom:0,maxZoom:0,centerZoom:0,center:[0,0],bounds:[-180,-85,180,85]},metadata:{vector_layers:[{id:'points',fields:{}}]}});
const asset=()=>({id,name:'Fixture only',source:source(),bytes:200,sha256:sha,createdAt:'2026-10-03T00:00:00Z',requestedBounds:[10,10,11,11],tileCoverageBounds:[-180,-85,180,85],minZoom:0,maxZoom:0,selection:'tile-aligned-pyramid',ranges:[{offset:147,bytes:53,sha256:sha}],tiles:[{coordinate:{z:0,x:0,y:0},bytes:53,sha256:sha,sourceOffset:147,packageOffset:147,layers:[{name:'points',features:1,version:2,extent:4096}]}],absent:[]});
test('tile selection respects exact boundaries, caps total work and remains finite for tiny regions',()=>{assert.deepEqual(tileSelection([0,-10,90,0],2,2),[{z:2,x:2,y:2}]);assert.equal(tileSelection([-122.55,37.65,-122.32,37.85],4,7).length,4);assert.throws(()=>tileSelection([-170,-70,170,70],0,10),/512/);assert.throws(()=>tileSelection([0,80,10,86],0,0),/Mercator/);assert.throws(()=>tileSelection([0,0,10,10],7,4));assert.equal(tileSelection([179.9999999999,0,180,1e-14],24,24).length,1);});
test('source validation rejects unsafe URLs, overlapping sections and mismatched discovery',()=>{assert.ok(validateTileSource(source()));for(const change of [s=>s.url+='?token=a',s=>s.header.metadataOffset=128,s=>s.header.tileLength=54,s=>s.etag='W/"fixture"',s=>s.ranges[0].bytes=128,s=>s.metadata.vector_layers.push(s.metadata.vector_layers[0])]){const s=source();change(s);assert.throws(()=>validateTileSource(s));}});
test('package validation binds coordinate membership and byte ranges',()=>{assert.ok(validateTilePackage(asset()));for(const change of [p=>p.tiles[0].coordinate.x=1,p=>p.absent.push({z:0,x:0,y:0}),p=>p.tiles[0].sourceOffset=128,p=>p.tiles[0].bytes=54,p=>p.tiles[0].packageOffset=190,p=>p.tiles[0].layers[0].version=3,p=>p.selection='polygon-clip']){const p=asset();change(p);assert.throws(()=>validateTilePackage(p));}});
test('desktop routing cannot fall back to network after native rejection',async()=>{const oldWindow=globalThis.window,oldFetch=globalThis.fetch;try{let invoked;globalThis.window={__TAURI__:{core:{invoke:async(...args)=>{invoked=args;throw 'native rejected';}}}};globalThis.fetch=()=>{throw new Error('Unexpected fallback');};await assert.rejects(tileRequest('extract',{sourceId:id,bounds:[10,10,11,11],minZoom:0,maxZoom:0}),/native rejected/);assert.equal(invoked[0],'extract_tiles');assert.deepEqual(invoked[1].request.bounds,[10,10,11,11]);}finally{globalThis.window=oldWindow;globalThis.fetch=oldFetch;}});
test('tile read rejects a reply for a different coordinate',async()=>{const oldWindow=globalThis.window;try{globalThis.window={__TAURI__:{core:{invoke:async()=>({coordinate:{z:0,x:0,y:0},dataBase64:null,sha256:null,layers:[]})}}};await assert.rejects(tileRequest('tile',{id,z:1,x:0,y:0}),/response/);}finally{globalThis.window=oldWindow;}});
const imported=()=>{const p=asset();p.source.url='';p.source.etag='';p.source.local={fileName:'中文.PMTILES',sha256:sha};p.requestedBounds=p.source.header.bounds;p.selection='imported-archive';return p;};
const mbtiles=()=>{const p=imported();delete p.source.header;p.source.local.fileName='地图.mbtiles';p.source.ranges=[];p.ranges=[];p.source.mbtiles={format:'pbf',scheme:'tms',minZoom:0,maxZoom:0,bounds:p.requestedBounds,addressedTiles:1};p.source.metadata.mbtiles={name:'Fixture only',format:'pbf',json:JSON.stringify(p.source.metadata)};delete p.tiles[0].sourceOffset;delete p.tiles[0].packageOffset;return p;};
test('MBTiles receipts use their actual descriptor and logical tile inventory',()=>{assert.ok(validateTilePackage(mbtiles()));for(const change of [p=>p.source.header=source().header,p=>p.source.mbtiles.scheme='xyz',p=>p.source.mbtiles.addressedTiles=2,p=>p.tiles[0].packageOffset=127,p=>p.source.local.fileName='wrong.pmtiles',p=>p.source.metadata.vector_layers[0].fields.a='Object',p=>p.tiles[0].layers[0].name='other',p=>p.tiles[0].image={width:256,height:256,contentType:'image/png'}]){const p=mbtiles();change(p);assert.throws(()=>validateTilePackage(p));}});
test('raster MBTiles validates image dimensions and cannot be mistaken for vectors',()=>{const p=mbtiles();p.source.mbtiles.format='png';p.source.mbtiles.tileSize=256;p.source.metadata.mbtiles.format='png';p.source.metadata.vector_layers=[];p.tiles[0].layers=[];p.tiles[0].image={width:256,height:256,contentType:'image/png'};assert.ok(validateTilePackage(p));for(const change of [p=>p.tiles[0].image.height=512,p=>p.tiles[0].image.contentType='text/html',p=>p.source.mbtiles.tileSize=2048]){const q=structuredClone(p);change(q);assert.throws(()=>validateTilePackage(q));}});
test('valid empty MVT receipts and responses remain readable',async()=>{const p=mbtiles();p.tiles[0].layers=[];assert.ok(validateTilePackage(p));const oldWindow=globalThis.window;try{const value={coordinate:{z:0,x:0,y:0},dataBase64:'',sha256:'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855',layers:[]};globalThis.window={__TAURI__:{core:{invoke:async()=>value}}};assert.deepEqual(await tileRequest('tile',{id,z:0,x:0,y:0}),value);}finally{globalThis.window=oldWindow;}});
test('incomplete MBTiles files report their own format before uploading',async()=>{const oldWindow=globalThis.window,oldFetch=globalThis.fetch;try{globalThis.window={};globalThis.fetch=()=>{throw new Error('Invalid files must not upload');};await assert.rejects(openTilePackage({name:'short.MBTILES',size:99}),/MBTiles SQLite/);}finally{globalThis.window=oldWindow;globalThis.fetch=oldFetch;}});
test('local import validates a sparse archive without inventing remote provenance',()=>{assert.ok(validateTilePackage(imported()));for(const change of [p=>p.source.local.fileName='C:\\file.pmtiles',p=>p.source.url='https://example.com/fixture.pmtiles',p=>p.source.etag='"version"',p=>p.source.local.sha256='b'.repeat(64),p=>p.tiles[0].packageOffset=148,p=>p.source.header.addressedTiles=2,p=>p.absent.push({z:0,x:0,y:0}),p=>p.requestedBounds=[10,10,11,11]]){const p=imported();change(p);assert.throws(()=>validateTilePackage(p));}});
test('native file selection supports cancellation and never falls back after rejection',async()=>{const oldWindow=globalThis.window,oldFetch=globalThis.fetch;try{let calls=[];globalThis.window={__TAURI__:{core:{invoke:async(...args)=>{calls.push(args);return null;}}}};globalThis.fetch=()=>{throw new Error('Unexpected fallback');};assert.equal(await openTilePackage(),null);assert.deepEqual(calls,[['open_tile_package']]);globalThis.window.__TAURI__.core.invoke=async()=>{throw 'Selection failed';};await assert.rejects(openTilePackage(),/Selection failed/);}finally{globalThis.window=oldWindow;globalThis.fetch=oldFetch;}});
test('development import sends exact file bytes to loopback and rejects excess before uploading',async()=>{const oldWindow=globalThis.window,oldFetch=globalThis.fetch;try{globalThis.window={};const file=new Blob([new Uint8Array(200)]);file.name='中文.PMTILES';let called=0;globalThis.fetch=async(url,options)=>{called++;assert.equal(url,'http://127.0.0.1:4318/tile-packages/import?name='+encodeURIComponent(file.name));assert.equal(options.body,file);assert.equal(options.headers['X-GeoD-Client'],'geod-global');return {ok:true,json:async()=>imported()};};assert.equal((await openTilePackage(file)).selection,'imported-archive');await assert.rejects(openTilePackage({name:'large.pmtiles',size:128*1024*1024+1}),/128 MiB/);await assert.rejects(openTilePackage({name:'wrong.zip',size:200}),/.pmtiles/);assert.equal(called,1);}finally{globalThis.window=oldWindow;globalThis.fetch=oldFetch;}});
